import{_ as t,o as i,c as s,a4 as r}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse('{"title":"ADR-0076 — Chaîne de publication : ce qui est vérifié est ce qui est signé","description":"Extrait de docs/adr/0076-ce-qui-est-verifie-est-ce-qui-est-signe.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0076 — Chaîne de publication : ce qui est vérifié est ce qui est signé","description":"Extrait de docs/adr/0076-ce-qui-est-verifie-est-ce-qui-est-signe.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0076-ce-qui-est-verifie-est-ce-qui-est-signe.md","filePath":"developpeurs/adr/0076-ce-qui-est-verifie-est-ce-qui-est-signe.md"}'),n={name:"developpeurs/adr/0076-ce-qui-est-verifie-est-ce-qui-est-signe.md"};function o(a,e,u,l,c,d){return i(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="adr-0076--chaîne-de-publication--ce-qui-est-vérifié-est-ce-qui-est-signé" tabindex="-1">ADR-0076 — Chaîne de publication : ce qui est vérifié est ce qui est signé <a class="header-anchor" href="#adr-0076--chaîne-de-publication--ce-qui-est-vérifié-est-ce-qui-est-signé" aria-label="Permalink to &quot;ADR-0076 — Chaîne de publication : ce qui est vérifié est ce qui est signé {#adr-0076--chaîne-de-publication--ce-qui-est-vérifié-est-ce-qui-est-signé}&quot;">​</a></h1><p><strong>Date :</strong> 4 novembre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> audit complet du 21 octobre 2026, constats EXP-19 (« L&#39;image vérifiée n&#39;est pas l&#39;image publiée »), EXP-24 (« L&#39;archive de la pile est seulement intègre, pas authentique ») et EXP-25 (« Aucun <code>environment:</code> protégé sur la publication des images ») ; lot 2 de l&#39;audit, accepté par le Product Owner le 21/10/2026 ; arbitrages du Product Owner du 04/11/2026 (signature de l&#39;archive traitée comme celle des images ; jeton confiné à un seul job) <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0045-deploiement-par-un-exploitant-non-developpeur">ADR-0045</a>, décision n°1 (vérification avant publication) ; <a href="/teuthis-cms-distribution/developpeurs/adr/0057-authenticite-des-images-a-l-installation">ADR-0057</a> (l&#39;authenticité s&#39;étend à l&#39;archive de la pile) ; <a href="/teuthis-cms-distribution/developpeurs/adr/0063-depot-public-de-distribution">ADR-0063</a> (le jeton du dépôt de distribution) <strong>Complète :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0062-signature-par-cosign-v3">ADR-0062</a> (cosign v3, bundles Sigstore) ; <a href="/teuthis-cms-distribution/developpeurs/adr/0075-socle-fige-et-correctifs-a-la-construction">ADR-0075</a> (deux constructions ne sont plus identiques)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p><strong>EXP-19.</strong> Le workflow <code>publication-images.yml</code> construisait les images deux fois : le job <code>verification</code> construisait l&#39;amd64, la faisait tourner et l&#39;analysait par Trivy ; le job <code>publication</code> reconstruisait sans cache, en amd64 et en arm64, poussait, puis signait. Depuis l&#39;<code>apk upgrade</code> à la construction (ADR-0075), ces deux constructions ne contiennent pas forcément les mêmes paquets : l&#39;essai et l&#39;analyse ne portaient pas sur l&#39;empreinte signée. Relancer <code>publication</code> repoussait aussi l&#39;étiquette <code>X.Y.Z</code> vers une autre empreinte.</p><p><strong>EXP-24.</strong> La commande <code>teuthis</code>, exécutée en root, télécharge l&#39;archive <code>teuthis-deploy-X.Y.Z.tar.gz</code> de la version cible, en vérifie la somme SHA-256, puis passe la main au script <code>teuthis</code> qu&#39;elle contient. L&#39;installateur fait de même. Or la somme vient de la même release du dépôt public de distribution : elle prouve que le fichier n&#39;a pas été abîmé, pas qui l&#39;a produit. Qui détient le jeton d&#39;écriture de ce dépôt (<code>JETON_DISTRIBUTION</code>) fait exécuter du code root à toutes les instances à leur mise à jour. Les images, elles, sont signées depuis l&#39;ADR-0057.</p><p><strong>EXP-25.</strong> Ce jeton était un secret de dépôt, lisible par tout job de tout workflow du dépôt, y compris le job <code>site</code>, qui installe et exécute des dépendances npm et Python. La publication PyPI, elle, passe par des environnements (<code>pypi</code>, <code>testpypi</code>).</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. Une seule construction, vérifiée par son empreinte, puis signée et étiquetée.</strong> En publication réelle :</p><ul><li><code>garde-version</code> refuse si l&#39;étiquette <code>X.Y.Z</code> existe déjà sur GHCR pour l&#39;une des trois images. <strong>Une étiquette <code>X.Y.Z</code> ne se republie jamais</strong> ; <code>X.Y</code> reste la seule étiquette mobile.</li><li><code>publication</code> construit les deux architectures et pousse <strong>par empreinte seule, sans étiquette</strong>, avec SBOM et provenance.</li><li><code>verification-publiee</code> tire ces empreintes et rejoue sur elles <code>verifier-images.sh</code> (amd64, exécutée) et <code>analyser-images.sh</code> (Trivy, amd64 <strong>et</strong> arm64, lues dans l&#39;index de l&#39;empreinte).</li><li><code>signature-et-etiquettes</code> signe chaque empreinte (<code>cosign sign</code>), puis pose <code>X.Y.Z</code> et <code>X.Y</code>, et relit chaque étiquette en recalculant l&#39;empreinte des octets servis par le registre : tout écart arrête la publication.</li><li>Une empreinte qui échoue reste orpheline sur GHCR, non signée et sans étiquette. Une publication interrompue se reprend par « Re-run failed jobs » ; une image à reconstruire demande une nouvelle version.</li><li>La répétition à blanc (<code>workflow_dispatch</code>) garde sa forme : construction amd64 vérifiée et analysée, construction multi-architecture sans poussée.</li></ul><p><strong>2. L&#39;archive de la pile et l&#39;installateur sont signés, et l&#39;archive est vérifiée avant d&#39;être ouverte.</strong></p><ul><li>Le job <code>archive-deploiement</code> signe <code>teuthis-deploy-X.Y.Z.tar.gz</code> et <code>installer.sh</code> par <code>cosign sign-blob</code> (bundles <code>….sigstore.json</code>, joints aux deux releases), avec la même identité que les images : le workflow <code>publication-images.yml</code> du dépôt du code, sur l&#39;étiquette <code>vX.Y.Z</code>. Le jeton du dépôt de distribution ne permet pas de produire cette signature.</li><li><code>teuthis</code> (mise à jour) et l&#39;installateur vérifient l&#39;archive par <code>cosign verify-blob</code> <strong>après sa somme et avant de l&#39;extraire</strong>.</li><li><strong>Même règle que pour les images</strong> (ADR-0057, ADR-0062) : sans cosign, ou avec un cosign antérieur à la v3, un avertissement dit ce qui est vérifié (la somme) et ce qui ne l&#39;est pas, et l&#39;opération continue. Avec cosign v3, la signature est <strong>exigée</strong> pour toute version cible à partir de la 0.11.2, première archive signée : bundle absent ou signature refusée arrêtent l&#39;opération avant toute modification. Une version cible antérieure est acceptée sur sa somme seule, avec un avertissement.</li><li>L&#39;installateur se vérifie à la main avant d&#39;être lancé (<code>cosign verify-blob</code>, commande dans les notes de chaque release et dans <code>deploy/LISEZMOI.md</code>) : il ne peut pas se vérifier lui-même.</li></ul><p><strong>3. Le jeton du dépôt de distribution ne sert que dans un job, dans un environnement.</strong></p><ul><li><code>JETON_DISTRIBUTION</code> devient un secret de l&#39;environnement <code>distribution</code>, et n&#39;apparaît que dans le dernier job, <code>distribution</code>, qui ne récupère pas le dépôt et n&#39;exécute aucun de ses scripts : il publie des fichiers déjà fabriqués, signés et contrôlés, les relit sans jeton (somme et signature), puis pousse le site déjà construit.</li><li>Le job <code>site</code> construit et contrôle le site sans ce jeton ; les notes de release se complètent avec le seul jeton du workflow.</li><li>L&#39;environnement est réservé aux étiquettes <code>v*.*.*</code>. Un relecteur obligatoire s&#39;y ajoute si l&#39;offre GitHub le permet : selon la documentation de GitHub, cette option n&#39;existe sur un dépôt privé qu&#39;avec l&#39;offre Enterprise.</li><li>Le jeton est à portée fine (<code>Contents: Read and write</code> sur le seul dépôt de distribution) et à expiration. Les réglages sont des gestes du Product Owner, décrits dans <code>docs/publier-une-version.md</code>, § 9.</li></ul><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Garder les deux constructions et analyser l&#39;image publiée après coup</strong></td><td>L&#39;étiquette <code>X.Y.Z</code> désignerait, le temps de l&#39;analyse, une image que rien n&#39;a éprouvée, et l&#39;archive en figerait peut-être l&#39;empreinte. Vérifier avant d&#39;étiqueter coûte un job, pas une construction de plus.</td></tr><tr><td><strong>Construire une seule fois et pousser avec les étiquettes, puis vérifier avant de signer</strong></td><td>Une image non signée et non vérifiée porterait l&#39;étiquette publique pendant la vérification, et une vérification ratée laisserait une étiquette à retirer à la main. La poussée par empreinte n&#39;expose rien.</td></tr><tr><td><strong>Exiger cosign sur tous les serveurs</strong></td><td>Rupture pour les instances existantes, qui ont été installées sans lui, et règle différente de celle des images. L&#39;avertissement dit précisément ce qui n&#39;est pas vérifié ; exiger cosign reste possible plus tard, pour les deux à la fois.</td></tr><tr><td><strong>Signer l&#39;archive par une clé gardée par le Product Owner (GPG, minisign)</strong></td><td>Une clé à garder, à faire tourner et à publier, alors que l&#39;identité OIDC du workflow est déjà celle que vérifient les images. Sigstore enregistre aussi chaque signature dans un journal public.</td></tr><tr><td><strong>Un relecteur obligatoire sur chaque job qui publie</strong></td><td>Indisponible sur un dépôt privé hors Enterprise ; et plusieurs approbations par publication, espacées dans le temps. Un seul job porte le jeton : c&#39;est lui qu&#39;il faut protéger.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>L&#39;image analysée et essayée est, à l&#39;octet près, celle que l&#39;exploitant tire et dont il vérifie la signature.</li><li>Une étiquette <code>X.Y.Z</code> désigne une seule empreinte, pour toujours.</li><li>Le détenteur du jeton de distribution peut remplacer un fichier de la release publique, mais plus faire accepter une archive à une instance qui a cosign v3 : il ne peut pas la signer au nom du workflow.</li><li>Le jeton n&#39;est plus exposé au code des dépendances du site.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>La protection de l&#39;archive commence avec la commande 0.11.2.</strong> Le passage depuis la 0.11.1 est conduit par la commande 0.11.1, qui ne vérifie que la somme ; la vérification vaut pour les mises à jour suivantes. (La 0.11.2 n&#39;ayant pas été distribuée, ce premier passage se fait vers la 0.11.3 : voir la mise à jour du 05/11/2026.)</li><li><strong>Sans cosign v3 sur le serveur, rien ne change</strong> pour l&#39;authenticité de l&#39;archive : seul l&#39;avertissement le dit.</li><li>L&#39;arm64 est analysée, pas exécutée.</li><li>Une image reconstruite demande une nouvelle version, même pour un échec de pure infrastructure après la pose de <code>X.Y.Z</code>.</li><li>La poussée par empreinte, la signature, la pose des étiquettes et le job <code>distribution</code> ne s&#39;éprouvent qu&#39;en vraie publication.</li></ul><h2 id="mise-à-jour-du-05112026--la-0112-na-pas-été-distribuée" tabindex="-1">Mise à jour du 05/11/2026 — la 0.11.2 n&#39;a pas été distribuée <a class="header-anchor" href="#mise-à-jour-du-05112026--la-0112-na-pas-été-distribuée" aria-label="Permalink to &quot;Mise à jour du 05/11/2026 — la 0.11.2 n&#39;a pas été distribuée {#mise-à-jour-du-05112026--la-0112-na-pas-été-distribuée}&quot;">​</a></h2><p>Publication de la 0.11.2 (run 42060197651). Ce que la décision n°1 prévoit a tenu : trois images construites une fois, poussées par empreinte, essayées et analysées sur cette empreinte, signées, étiquetées <code>0.11.2</code> et <code>0.11</code> et relues ; archive et installateur signés et relus. Puis l&#39;API des releases de GitHub a répondu 502 au job des notes, <strong>tout en enregistrant la modification</strong>, et 500 à sa relance ; une relance de tous les jobs a ensuite été refusée par la garde de cohérence, puisque <code>0.11.2</code> existait sur GHCR. Le run ne pouvait plus aboutir : le site et le job <code>distribution</code> n&#39;ont pas tourné, et le dépôt de distribution n&#39;a jamais reçu la 0.11.2. Les instances ne la voient donc pas.</p><p>C&#39;est la garde voulue par la décision n°1, pas un défaut : elle a empêché de reconstruire d&#39;autres empreintes sous une étiquette publiée. Le défaut était ailleurs : les étapes qui écrivent sur une release n&#39;étaient pas rejouables. Elles le sont depuis la 0.11.3 : cinq essais à délai croissant sur une erreur passagère, création de release seulement si elle manque, et section « Images publiées » ajoutée une seule fois (relue avant chaque essai). <code>docs/publier-une-version.md</code> dit de ne jamais relancer tous les jobs. Les images 0.11.2 restent sur GHCR, signées ; la 0.11.3 les remplace.</p><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Workflow : une construction poussée par empreinte, vérification et analyse de l&#39;empreinte, signature puis étiquettes relues, refus de republier <code>X.Y.Z</code>, signature de l&#39;archive et de l&#39;installateur, jeton confiné au job <code>distribution</code>. — <code>.github/workflows/publication-images.yml</code>, <code>.github/scripts/verifier-images.sh</code> (images fournies par <code>IMAGE_API</code>, <code>IMAGE_ADMIN</code>, <code>IMAGE_FRONT</code>), <code>.github/scripts/analyser-images.sh</code> (<code>--platform</code>, lecture dans le registre). Preuves : actionlint 1.7.12 et shellcheck 0.11.0 sans alerte ; <code>verifier-images.sh</code> rejoué le 04/11/2026 sur les images 0.11 publiées, tirées par empreinte, et sur les trois images construites depuis le dépôt ; <code>analyser-images.sh --platform linux/arm64</code> lit bien la variante arm64.</li><li>[x] Vérification de l&#39;archive par <code>teuthis</code> et l&#39;installateur. — <code>deploy/teuthis</code>, <code>deploy/installer.sh</code>, <code>deploy/LISEZMOI.md</code>. Preuves : 18 tests bats ajoutés (10 dans <code>deploy/tests/teuthis.bats</code>, 8 dans <code>deploy/tests/installer.bats</code>), avec un faux cosign : signature valide, refusée, bundle absent, cosign absent ou en v2, version antérieure à la 0.11.2, archive locale, délégation ; 315 tests réussis sur 315 (297 avant) ; shellcheck 0.11.0 sans alerte. Le vrai <code>cosign verify-blob</code> contre Sigstore ne s&#39;éprouve qu&#39;à la 0.11.2.</li><li>[x] Procédure : chaîne décrite, répétition à blanc, <code>cosign verify-blob</code>, réglages de l&#39;environnement. — <code>docs/publier-une-version.md</code>, §§ 4, 6, 7 et 9.</li><li>[x] <strong>Créer l&#39;environnement <code>distribution</code></strong> (étiquettes <code>v*.*.*</code>, relecteur si l&#39;offre le permet), y ranger un jeton à portée fine et à expiration, <strong>supprimer le secret de dépôt</strong> et révoquer l&#39;ancien jeton. Geste du Product Owner, fait le 05/11/2026. — Preuves (relevées par <code>gh</code> le 05/11/2026) : l&#39;environnement existe, sa seule règle est l&#39;étiquette <code>v*.*.*</code>, aucune branche ; <code>JETON_DISTRIBUTION</code> est un secret de l&#39;environnement (posé le 05/11/2026) et le dépôt n&#39;a plus aucun secret. Aucun relecteur obligatoire : l&#39;option n&#39;existe pas sur ce dépôt privé, la restriction aux étiquettes fait la protection. Portée du jeton (<code>teuthis-cms-distribution</code> seul, Contents en lecture et écriture), expiration et révocation de l&#39;ancien : vérifiées par le Product Owner dans les réglages, l&#39;API ne les montrant pas.</li><li>[ ] <strong>Éprouver la chaîne jusqu&#39;au dépôt de distribution, sur la publication réelle de la 0.11.3</strong> : la 0.11.2 a éprouvé la poussée par empreinte, la vérification de l&#39;empreinte, la signature, les étiquettes relues et la signature de l&#39;archive et de l&#39;installateur (run 42060197651), mais pas les notes, le site ni le job <code>distribution</code> (voir la mise à jour du 05/11/2026). Restent : la relecture sans jeton, <code>cosign verify-blob</code> de l&#39;archive 0.11.3 téléchargée du dépôt de distribution, et une mise à jour d&#39;essai depuis la 0.11.3 vers la version suivante, pour voir la commande vérifier l&#39;archive.</li></ul>',25)])])}const m=t(n,[["render",o]]);export{g as __pageData,m as default};
